#include <string>
#include <unordered_map>
#include <regex>

// Markdown to HTML conversion rules
static const std::unordered_map<std::string, std::string> md_to_html {
    {"#", "<h1>"},
    {"##", "<h2>"},
    {"###", "<h3>"},
    {"####", "<h4>"},
    {"#####", "<h5>"},
    {"######", "<h6>"},
    {"*", "<em>"},
    {"**", "<strong>"},
    {"`", "<code>"},
    {"[", "<a href='"],
    {"]", "'>"],
    {"(", "<span class='math'>("},
    {")", ")</span>"},
    {"\\n", "<br/>"},
    {"\\s+", " "}, // replace multiple spaces with a single space
};

static std::string escape_html(const std::string& input) {
    static const std::regex re(R"(\\x[0-9A-Fa-f]{2})");
    std::string output;
    output.reserve(input.size());
    for (char c : input) {
        if (c == '&') output += "&amp;";
        else if (c == '<') output += "&lt;";
        else if (c == '>') output += "&gt;";
        else if (std::regex_match(std::string(&c, 1), re)) { // escape HTML entities
            unsigned char code = static_cast<unsigned char>(c);
            output += "&#" + std::to_string(static_cast<unsigned int>(code)) + ";";
        }
        else output += c;
    }
    return output;
}

std::string convert_markdown_to_html(const std::string& markdown) {
    std::string html;
    std::string::const_iterator it = markdown.begin();
    std::string::const_iterator end = markdown.end();

    while (it != end) {
        std::string token;
        while (it != end && std::isspace(static_cast<unsigned char>(*it))) ++it; // skip whitespace

        if (it == end) break; // reached end of input

        char open = *it; // save opening character
        ++it;

        if (open == '#') {
            int level = 0;
            while (it != end && std::isdigit(static_cast<unsigned char>(*it))) {
                level = level * 10 + (*it - '0');
                ++it;
            }
            token = "<h" + std::to_string(level) + ">";
        }
        else if (open == '*' || open == '**' || open == '`') {
            int count = 1;
            while (it != end && (open == '*' ? (*it) == '*' : (*it) == open)) {
                count += (open == '*' ? 1 : 2);
                ++it;
            }
            std::string tag = open == '*' ? "em" : (open == "**" ? "strong" : "code");
            token = "<" + tag + " class='md-" + std::to_string(count) + "'>" + escape_html(std::string(it - count, count)) + "</" + tag + ">";
            it += count;
        }
        else if (open == '[') {
            std::string href;
            std::string label;
            while (it != end && *it != ']') {
                if (*it == '(') {
                    std::string math;
                    while (it != end && *it != ')') {
                        if (*it == '\\') ++it; // skip backslash
                        math += *it;
                        ++it;
                    }
                    ++it; // skip closing parenthesis
                    token += "<span class='math'>" + math + "</span>";
                }
                else if (*it == '#') {
                    int level = 0;
                    while (it != end && std::isdigit(static_cast<unsigned char>(*it))) {
                        level = level * 10 + (*it - '0');
                        ++it;
                    }
                    token += "<h" + std::to_string(level) + ">";
                }
                else if (*it == '(' || *it == ')' || *it == '#' || std::isspace(static_cast<unsigned char>(*it))) {
                    break;
                }
                if (*it == ',') {
                    ++it;
                    if (*it == '"') {
                        ++it;
                        while (it != end && *it != '"') {
                            href += *it;
                            ++it;
                        }
                        ++it; // skip closing quote
                    }
                    else {
                        while (it != end && !std::isspace(static_cast<unsigned char>(*it))) {
                            href += *it;
                            ++it;
                        }
                    }
                }
                else {
                    while (it != end && !std::isspace(static_cast<unsigned char>(*it))) {
                        label += *it;
                        ++it;
                    }
                }
            }
            ++it; // skip closing bracket

            if (!href.empty()) {
                token += "<a href='" + escape_html(href) + "'>";
            }
            token += escape_html(label);
            if (!href.empty()) {
                token += "</a>";
            }
        }
        else if (open == '(') {
            std::string math;
            while (it != end && *it != ')') {
                if (*it == '\\') ++it; // skip backslash
                math += *it;
                ++it;
            }
            ++it; // skip closing parenthesis
            token = "<span class='math'>" + math + "</span>";
        }
        else if (*it == '\\') { // escape backslash
            token += "\\\\";
            ++it;
        }
        else if (*it == '\\n') { // line break
            token += "<br/>";
            ++it;
        }
        else { // plain text
            while (it != end && !std::isspace(static_cast<unsigned char>(*it))) {
                token += *it;
                ++it;
            }
        }

        html += md_to_html[open] + token + "</" + md_to_html[open] + ">";
    }

    return html;
}

int main() {
    std::string markdown = "Hello **world**! # This is a [link](https://example.com) to an example page. Here is some inline \\math: \\(x^2 + y^2 = z^2\\). And some code: `printf(\"Hello, world!\\n\");`";
    std::string html = convert_markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This implementation uses a lookup table `md_to_html` to convert Markdown syntax to HTML tags. It also defines a helper function `escape_html` to escape special characters in the input text.

The main `convert_markdown_to_html` function iterates over the input string character by character, building up a `token` string for each Markdown element. It handles various Markdown constructs, such as headers, emphasis, code spans, links, inline math, and line breaks.

Note that this implementation is not comprehensive and may not handle all possible Markdown variations. You may need to adjust the conversion rules and the regular expressions used to match Markdown elements based on your specific use case.

